  static final Map<String, BankBrand> _byKey = {
    for (final b in all) b.key: b,
  };

  static BankBrand? findByKey(String? key) {
    if (key == null || key.isEmpty) return null;
    return _byKey[key];
  }

  /// Mencari merk paling cocok berdasarkan kunci tersimpan atau nama akun.
  static BankBrand? resolve({String? logoKey, required String accountName}) {
    final exact = findByKey(logoKey);
    if (exact != null) return exact;

    final lower = accountName.trim().toLowerCase();
    if (lower.isEmpty) return null;

    // 1. Cek kecocokan persis dengan displayName atau key
    if (lower == 'dompet') return findByKey('cash');
    for (final brand in all) {
      if (lower == brand.key || lower == brand.displayName.toLowerCase()) {
        return brand;
      }
    }

    // 2. Cek batas kata (word boundary) atau alias terpanjang lebih dulu
    BankBrand? bestMatch;
    int bestAliasLen = 0;
    for (final brand in all) {
      for (final alias in brand.aliases) {
        if (alias.length < 2) continue;
        if (_matchesWordOrSubstring(lower, alias)) {
          if (alias.length > bestAliasLen) {
            bestAliasLen = alias.length;
            bestMatch = brand;
          }
        }
      }
    }
    return bestMatch;
  }

  static bool _matchesWordOrSubstring(String input, String alias) {
    // Untuk alias pendek (<= 3 huruf seperti bca, bni, bri, bsi, ovo, uob, dbs),
    // wajib cocok sebagai kata utuh agar tidak salah cocok (misal 'pribadi' != 'bri')
    if (alias.length <= 3) {
      final escaped = RegExp.escape(alias);
      return RegExp(r'(^|[^a-z0-9])' + escaped + r'([^a-z0-9]|$)').hasMatch(input);
    }
    return input.contains(alias);
  }
